class Solution:
    def tripletCount(self, a: List[int], b: List[int], c: List[int]) -> int:
        def eo(arr):
            e = sum(1 for x in arr if bin(x).count('1') % 2 == 0)
            return e, len(arr) - e
        ea, oa = eo(a); eb, ob = eo(b); ec, oc = eo(c)
        return (ea*eb*ec + ea*ob*oc + oa*eb*oc + oa*ob*ec)

