class Solution {
    private long[] eo(int[] v){
        long e=0;
        for(int x:v) if(Long.bitCount(x)%2==0) ++e;
        return new long[]{e, v.length-e};
    }
    public long tripletCount(int[] a, int[] b, int[] c){
        long[] A=eo(a), B=eo(b), C=eo(c);
        return A[0]*B[0]*C[0] + A[0]*B[1]*C[1] + A[1]*B[0]*C[1] + A[1]*B[1]*C[0];
    }
}

