var tripletCount = function(a, b, c) {
    const eo = (arr) => {
        let e = 0;
        for (const x of arr) {
            let p = 0, t = x;
            while (t) { p ^= t & 1; t >>= 1; }
            if (p === 0) ++e;
        }
        return e;
    };
    const ea = eo(a), ob = b.length - eo(b), ec = eo(c);
    const oa = a.length - ea, eb = b.length - ob, oc = c.length - ec;
    return ea*eb*ec + ea*ob*oc + oa*eb*oc + oa*ob*ec;
};

